(* assnHasOr reports whether a contains a disjunction anywhere.

   go: check.go:45:6 *)
Definition assnHasOrⁱᵐᵖˡ {ext : ffi_syntax} {go_gctx : GoGlobalContext} : val :=
  λ: "a",
    exception_do (let: "a" := (GoAlloc (go.PointerType Assn) "a") in
    (if: Convert go.untyped_bool go.bool ((![go.PointerType Assn] "a") =⟨go.PointerType Assn⟩ (Convert go.untyped_nil (go.PointerType Assn) UntypedNil))
    then return: (#false)
    else do:  #());;;
    (if: Convert go.untyped_bool go.bool ((![AssnKind] (StructFieldRef Assn "Kind"%go (![go.PointerType Assn] "a"))) =⟨AssnKind⟩ AOr)
    then return: (#true)
    else do:  #());;;
    (if: let: "$a0" := (![go.PointerType Assn] (StructFieldRef Assn "L"%go (![go.PointerType Assn] "a"))) in
    (FuncResolve assnHasOr [] #()) "$a0"
    then return: (#true)
    else do:  #());;;
    return: (let: "$a0" := (![go.PointerType Assn] (StructFieldRef Assn "R"%go (![go.PointerType Assn] "a"))) in
     (FuncResolve assnHasOr [] #()) "$a0")).

