(* assnWellSorted sort-checks a precondition: every atom must be well-sorted,
   and no form other than emp, ∗ and the two atoms may appear.

   go: check.go:74:6 *)
Definition assnWellSortedⁱᵐᵖˡ {ext : ffi_syntax} {go_gctx : GoGlobalContext} : val :=
  λ: "se" "a",
    exception_do (let: "a" := (GoAlloc (go.PointerType Assn) "a") in
    let: "se" := (GoAlloc (go.PointerType sortEnv) "se") in
    (if: Convert go.untyped_bool go.bool ((![go.PointerType Assn] "a") =⟨go.PointerType Assn⟩ (Convert go.untyped_nil (go.PointerType Assn) UntypedNil))
    then return: (Convert go.untyped_nil (go.PointerType Failure) UntypedNil)
    else do:  #());;;
    (if: Convert go.untyped_bool go.bool ((![AssnKind] (StructFieldRef Assn "Kind"%go (![go.PointerType Assn] "a"))) =⟨AssnKind⟩ AEmp)
    then return: (Convert go.untyped_nil (go.PointerType Failure) UntypedNil)
    else do:  #());;;
    (if: Convert go.untyped_bool go.bool ((![AssnKind] (StructFieldRef Assn "Kind"%go (![go.PointerType Assn] "a"))) =⟨AssnKind⟩ ASep)
